<template>
  <section class="reg-shell"><header><div><small>PATIENT IDENTITY</small><h2>Registration</h2><p>Verified demographics, contact and encounter identifiers.</p></div><v-btn v-if="canEdit" x-small depressed color="#0f766e" dark @click="openEdit"><v-icon x-small left>mdi-account-edit-outline</v-icon>Update registration</v-btn></header>
    <div class="identity-band"><div class="barcode"><v-icon>mdi-barcode</v-icon><strong>{{ patient.barcode||'Barcode pending' }}</strong><small>MRN {{ patient.mrn||'Pending' }}</small></div><div><strong>{{ fullName }}</strong><span>{{ patient.dob||'DOB not filed' }} · {{ patient.gender||patient.sex||'Sex not filed' }}</span></div><v-btn small outlined color="#0f766e" @click="printBand"><v-icon small left>mdi-printer-outline</v-icon>Print wristband</v-btn></div>
    <div class="reg-grid"><section><h3>Identity</h3><p><span>Full name</span><b>{{ fullName }}</b></p><p><span>Date of birth</span><b>{{ patient.dob||'-' }}</b></p><p><span>Sex</span><b>{{ patient.gender||patient.sex||'-' }}</b></p><p><span>National ID</span><b>{{ patient.nationalId||'-' }}</b></p></section><section><h3>Contact</h3><p><span>Phone</span><b>{{ patient.phone||'-' }}</b></p><p><span>Address</span><b>{{ patient.address||'-' }}</b></p><p><span>Region</span><b>{{ patient.region||'-' }}</b></p><p><span>Emergency contact</span><b>{{ patient.emergencyContact||'-' }}</b></p></section><section><h3>Administrative</h3><p><span>Payment class</span><b>{{ patient.paymentClass||patient.insurance||'Self-pay / verify' }}</b></p><p><span>Language</span><b>{{ patient.preferredLanguage||'French / English' }}</b></p><p><span>PHI basis</span><b>{{ patient.phiAccessBasis||'Treatment' }}</b></p><p><span>Status</span><b>{{ patient.patientStatus||patient.status||'Active' }}</b></p></section></div>
    <v-dialog v-model="dialog" max-width="720" persistent><v-card><v-card-title class="dialog-title">Update patient registration<v-spacer/><v-btn icon small @click="dialog=false"><v-icon>mdi-close</v-icon></v-btn></v-card-title><v-card-text class="pt-4"><div class="form-grid"><v-text-field v-model="form.firstName" label="First name" dense outlined/><v-text-field v-model="form.lastName" label="Last name" dense outlined/><v-text-field v-model="form.dob" type="date" label="Date of birth" dense outlined/><v-select v-model="form.gender" :items="['Female','Male','Intersex','Unknown']" label="Sex" dense outlined/><v-text-field v-model="form.phone" label="Phone" dense outlined/><v-text-field v-model="form.emergencyContact" label="Emergency contact" dense outlined/><v-text-field v-model="form.address" label="Address / village" dense outlined/><v-text-field v-model="form.region" label="Region" dense outlined/><v-text-field v-model="form.paymentClass" label="Payment / insurance class" dense outlined/><v-select v-model="form.preferredLanguage" :items="['French','English','French / English','Other']" label="Preferred language" dense outlined/></div></v-card-text><v-card-actions><v-spacer/><v-btn text small @click="dialog=false">Cancel</v-btn><v-btn small depressed color="#0f766e" dark :loading="saving" @click="save">Save changes</v-btn></v-card-actions></v-card></v-dialog>
  </section>
</template>
<script>
export default{name:'Patient360RegistrationTab',props:{patientId:{type:String,required:true},patient:{type:Object,default:()=>({})},role:{type:String,default:''},readOnly:Boolean},data:()=>({dialog:false,saving:false,form:{}}),computed:{canEdit(){return !this.readOnly&&['ADMIN','FRONT_DESK','RECORDS','NURSE'].includes(this.role)},fullName(){return this.patient.name||[this.patient.firstName,this.patient.lastName].filter(Boolean).join(' ')||'Unnamed patient'}},methods:{openEdit(){this.form={firstName:this.patient.firstName||this.fullName.split(' ')[0]||'',lastName:this.patient.lastName||this.fullName.split(' ').slice(1).join(' '),dob:this.patient.dob||'',gender:this.patient.gender||this.patient.sex||'',phone:this.patient.phone||'',emergencyContact:this.patient.emergencyContact||'',address:this.patient.address||'',region:this.patient.region||'',paymentClass:this.patient.paymentClass||this.patient.insurance||'',preferredLanguage:this.patient.preferredLanguage||'French / English'};this.dialog=true},async save(){this.saving=true;try{const updates={...this.form,name:[this.form.firstName,this.form.lastName].filter(Boolean).join(' ')};await this.$store.dispatch('clinical/updatePatient',{patientId:this.patientId,updates});await this.$store.dispatch('clinical/createDocument',{patientId:this.patientId,title:'Registration update',category:'Registration',content:'Patient demographics and contact information verified.',status:'Filed'});this.dialog=false;this.$emit('saved')}finally{this.saving=false}},printBand(){const w=window.open('','_blank','width=560,height=360');if(!w)return;w.document.write(`<html><head><title>Patient wristband</title><style>body{font-family:Arial;padding:24px}.band{border:2px solid #111;padding:18px;width:430px}.code{font-family:monospace;font-size:22px;letter-spacing:2px}</style></head><body><div class="band"><h2>${this.fullName}</h2><p>MRN ${this.patient.mrn||'-'} | DOB ${this.patient.dob||'-'}</p><div class="code">${this.patient.barcode||this.patient.mrn||this.patientId}</div></div><script>window.print()<\/script></body></html>`);w.document.close()}}}
</script>
<style scoped>
.reg-shell{padding:14px;background:#f8fbfb;min-height:100%}.reg-shell>header{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #0f766e;padding-bottom:10px}.reg-shell small{font-weight:900;color:#64748b}.reg-shell h2{font-size:18px;margin:2px 0}.reg-shell p{margin:0;font-size:12px}.identity-band{display:grid;grid-template-columns:auto 1fr auto;gap:18px;align-items:center;padding:14px;background:#e7f3f1;border:1px solid #99c8c2;margin:12px 0}.identity-band>div{display:flex;flex-direction:column}.barcode strong{font-family:monospace}.reg-grid{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #cbd5e1;background:white}.reg-grid section{padding:12px;border-right:1px solid #e2e8f0}.reg-grid h3{font-size:13px;color:#0f766e}.reg-grid p{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid #edf2f7;padding:7px 0}.reg-grid span{color:#64748b}.reg-grid b{text-align:right}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.dialog-title{font-size:16px!important;font-weight:900}@media(max-width:800px){.reg-grid{grid-template-columns:1fr}.identity-band{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}}
</style>
